import json,itertools,datetime
x=json.loads(context)
D=x['skus']; V={v['id']:v for v in x['vendors']}
opts={s:[] for s in D}
for q in x['quotes']:
 d=D[q['sku']]
 if q['quality']=='approved' and d['demand']<=q['units']<=d['demand']+2 and q['arrival']<=d['deadline']:
  opts[q['sku']].append(q)
best=None
for qs in itertools.product(*(opts[s] for s in sorted(D))):
 bysku={q['sku']:q for q in qs}
 if any(q['needs_same_vendor_sku'] and bysku[q['needs_same_vendor_sku']]['vendor']!=q['vendor'] for q in qs): continue
 vendors={}
 for q in qs:
  a=vendors.setdefault(q['vendor'],{'units':0,'gross':0,'skus':set()})
  a['units']+=q['units']; a['gross']+=q['units']*q['unit_cents']; a['skus'].add(q['sku'])
 if len(vendors)<3 or any(a['units']>V[v]['unit_cap'] for v,a in vendors.items()): continue
 if sum(q['carbon'] for q in qs)>x['carbon_cap']: continue
 total=0
 for v,a in vendors.items():
  r=V[v]; gross=a['gross']; disc=(gross*r['tier_bps']+5000)//10000 if a['units']>=r['tier_units'] else 0
  merch=gross-disc
  total+=merch+(0 if gross>=r['free_shipping_gross'] else r['shipping_cents'])
  if len(a['skus'])>=2 and merch>=r['rebate_merchandise_min']: total-=r['rebate_cents']
 if best is None or total<best: best=total
print(FINAL(str(best)))
